}

# B. shell-snapshots/ 전체
$ssDir = "C:\Users\edn_y\.claude\shell-snapshots"
if (Test-Path $ssDir) {
    $count = (Get-ChildItem $ssDir -File).Count
    Get-ChildItem $ssDir -File | Remove-Item -Force
    Write-Host "shell-snapshots: $count files deleted"
}

# C. plans/ - starry-skipping-crown.md 제외 전부 삭제
$plansDir = "C:\Users\edn_y\.claude\plans"
$deleted = Get-ChildItem $plansDir -File | Where-Object { $_.Name -ne "starry-skipping-crown.md" }
$deletedCount = $deleted.Count
$deleted | Remove-Item -Force
Write-Host "plans/: $deletedCount files deleted"

# D. 기타 소파일
$misc = @(
    "C:\Users\edn_y\.claude\cache\changelog.md",
    "C:\Users\edn_y\.claude\ide\15202.lock",
    "C:\Users\edn_y\.claude\settings.json.bak",
    "C:\Users\edn_y\.claude\templates\rtk-completion-log.md"
)
foreach ($f in $misc) {
    if (Test-Path $f) { Remove-Item -Force $f; Write-Host "Deleted: $f" }
    else { Write-Host "Not found: $f" }
}

# E. backups/ - 최신 2개 유지, 나머지 삭제
