if (Test-Path $backupsDir) {
    $toDelete = Get-ChildItem $backupsDir -File | Sort-Object LastWriteTime -Descending | Select-Object -Skip 2
    $toDelete | Remove-Item -Force
    Write-Host "backups/: $($toDelete.Count) old backups deleted"
}

# F. session-env/ 빈 디렉토리
$seDir = "C:\Users\edn_y\.claude\session-env"
if (Test-Path $seDir) {
